/*
 * Igreja Master — sistema visual branco/azul, versão 3.7.26.
 * Camada aditiva: preserva a marcação e as funcionalidades dos módulos atuais.
 * As variáveis --church-* são definidas apenas com cores HEX validadas no PHP.
 */
:root {
  --church-primary: #0D47A1;
  --church-secondary: #1976D2;
  --ui-blue: var(--church-primary);
  --ui-blue-dark: color-mix(in srgb, var(--church-primary), #071d46 22%);
  --gold: var(--church-primary);
  --gold2: var(--church-secondary);
  --bg: #f3f7fc;
  --ui-ink: #112b50;
  --ui-muted: #657893;
  --ui-line: #dfebf7;
  --ui-radius: 17px;
  --shadow: 0 5px 22px rgba(12, 55, 109, .065);
}
body {
  --ui-blue: var(--church-primary);
  --ui-blue-dark: color-mix(in srgb, var(--church-primary), #071d46 22%);
  --gold: var(--church-primary);
  --gold2: var(--church-secondary);
  background: #f3f7fc;
  color: var(--ui-ink);
  font-family: Inter, system-ui, -apple-system, "Segoe UI", sans-serif;
}
.app-shell { min-height: 100vh; }
.sidebar {
  background: linear-gradient(180deg, #0b376c 0%, #08254b 68%, #071d3c 100%);
  border-right: 1px solid rgba(255,255,255,.14);
  color: #f3f8ff;
}
.sidebar .brand { background: rgba(255,255,255,.035); border-bottom: 1px solid rgba(255,255,255,.12); }
.sidebar .brand strong { color: #fff; font-size: 15px; line-height: 1.35; }
.sidebar .brand small { color: #c8dbf5; }
.sidebar .brand-logo {
  background: linear-gradient(140deg, var(--church-secondary), var(--church-primary));
  border: 1px solid rgba(255,255,255,.27);
  color: #fff;
  box-shadow: 0 5px 18px rgba(1,17,45,.2);
}
.sidebar .brand-logo img { width: 100%; height: 100%; object-fit: contain; }
.sidebar .nav-group summary { color: #d4e5fa; font-size: 12px; }
.sidebar .nav-group summary:hover { color: #fff; }
.sidebar .nav-group-links { border-color: rgba(255,255,255,.22); }
.sidebar .nav-item { color: #e2edfa; font-size: 12px; }
.sidebar .nav-item:hover { background: rgba(255,255,255,.1); }
.sidebar .nav-item.active {
  background: var(--church-primary);
  color: #fff;
  box-shadow: inset 3px 0 0 #fff, 0 5px 15px rgba(0,0,0,.08);
}
.sidebar .nav-search, .sidebar .current-church {
  background: rgba(255,255,255,.06);
  border-color: rgba(255,255,255,.2);
  color: #eff6ff;
}
.sidebar .current-church span, .sidebar .nav-search span { color: #f0f6ff; }
.app-topbar {
  min-height: 73px;
  background: rgba(255,255,255,.96);
  border-bottom-color: #e1ebf5;
  box-shadow: 0 4px 16px rgba(14,55,105,.035);
}
.breadcrumb strong { font-size: 16px; color: #0e3265; }
.breadcrumb>span { color: #5e799b; }
.content { padding-top: 29px; }
.content > .page-head h1, .module-title h1 { color: #0f376b; }
.content > .page-head p, .module-title p { color: #70849d; }
.content .card, .content .stat {
  background: #fff;
  border: 1px solid #e2eaf4;
  border-radius: 17px;
  box-shadow: 0 6px 22px rgba(18,61,111,.05);
}
.content .card-pad { padding: 23px; }
.content h2 { color: #173b6e; }
.content .stat-value { color: #0e3c7f; }
.btn-primary, .btn.primary {
  background: var(--church-primary);
  border-color: transparent;
  box-shadow: 0 5px 13px color-mix(in srgb, var(--church-primary), transparent 80%);
  color: #fff;
}
.btn-primary:hover, .btn.primary:hover {
  background: color-mix(in srgb, var(--church-primary), #061d41 19%);
  color: #fff;
}
.btn-light { background: #f9fbff; border-color: #cbddec; color: #12406e; }
.btn-light:hover { background: #eaf4ff; border-color: #8fbbe5; }
.btn, .button { border-radius: 10px; }
input.input, select.select, textarea.textarea,
input:not([type=checkbox]):not([type=radio]):not([type=hidden]),
.content select, .content textarea {
  border-radius: 10px;
}
.content input:focus-visible, .content select:focus-visible, .content textarea:focus-visible {
  outline-color: var(--church-secondary);
}
.content .table-wrap { border: 1px solid #e4ebf4; background: #fff; }
.content .table th, .content table th { background: #f0f6fd; color: #426184; }
.content .table tbody tr:hover, .content table tbody tr:hover { background: #f8fbff; }
.content .app-dialog, .app-dialog { border-radius: 19px; }
.dialog-heading { background: linear-gradient(180deg,#fff,#f9fcff); }
.app-dialog .dialog-heading h2 { color: #13396e; }
.app-dialog .field label { color: #234979; }
.app-footer { background: #fff; border-top: 1px solid #e0eaf5; }
.branding-layout {
  display: grid;
  grid-template-columns: minmax(0,1.18fr) minmax(300px,.82fr);
  gap: 20px;
  align-items: start;
}
.content .branding-panel { padding: 26px; overflow: visible; }
.branding-section-kicker {
  text-transform: uppercase;
  letter-spacing: .11em;
  color: var(--church-primary);
  font-weight: 780;
  font-size: 10px;
}
.branding-section-heading h2 { margin: 5px 0 4px; font-size: 21px!important; }
.branding-section-heading p { max-width: 600px; font-size: 13px; color: #6a7f9a; margin: 0 0 25px; }
.branding-form { display: grid; gap: 19px; }
.branding-form .field { display: grid; gap: 7px; }
.branding-form .field label { font-size: 12px; font-weight: 720; color: #1c426f; }
.branding-form .field small { color: #697f98; line-height: 1.5; }
.branding-upload {
  display: flex;
  gap: 18px;
  align-items: center;
  border: 1px dashed #adcae7;
  border-radius: 14px;
  padding: 18px;
  background: #f5faff;
}
.branding-upload strong { color: #123a70; font-size: 14px; }
.branding-upload p { color: #647b96; font-size: 12px; margin: 3px 0 10px; }
.branding-upload input[type=file] { width: 100%; max-width: 320px; font-size: 12px; }
.branding-logo-preview {
  width: 88px; height: 88px; min-width: 88px;
  display: grid; place-items: center;
  border: 1px solid #dae5f2;
  border-radius: 16px; background: #fff;
  color: var(--church-primary); font-size: 39px;
  overflow: hidden;
}
.branding-logo-preview img, .branding-preview-mark img {
  width: 100%; height: 100%; object-fit: contain;
}
.branding-color-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:16px; }
.branding-color-grid input[type=color] {
  width: 100%; max-width: 180px; height: 48px; cursor:pointer;
  padding: 4px; border-radius: 9px; background:#fff; border:1px solid #cedcea;
}
.branding-actions { padding-top: 7px; }
.branding-actions .btn { min-height: 46px; }
.branding-remove-form { margin-top: 12px; }
.branding-preview-panel { position: sticky; top: 96px; }
.branding-preview-brand {
  display:flex; align-items:center; gap:14px;
  background: linear-gradient(115deg,var(--church-primary),var(--church-secondary));
  padding: 20px; border-radius: 15px; color:#fff; min-height: 96px;
}
.branding-preview-brand strong, .branding-preview-brand small { display:block; color: #fff; }
.branding-preview-brand strong { font-size: 15px; font-weight: 780; line-height:1.4; }
.branding-preview-brand small { opacity:.92; font-size:11px; margin-top:3px; }
.branding-preview-mark { display:grid;place-items:center;flex:0 0 55px;
  width:55px;height:55px;background:#fff;border-radius:12px;overflow:hidden;
  font-size:27px;color:var(--church-primary); }
.branding-sample-content {
  background: #f5faff; margin-top: 16px; padding: 20px; border-radius: 14px;
  border: 1px solid #e2edf8;
}
.branding-sample-label { color:var(--church-primary);font-size:11px;text-transform:uppercase;font-weight:780;letter-spacing:.06em; }
.branding-sample-content h3 { margin:8px 0 4px; color:#173c70; font-size:17px!important; }
.branding-sample-content p { color:#6a7e95;font-size:12px;line-height:1.6; }
.branding-sample-stats { display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin:15px 0; }
.branding-sample-stats>div { border:1px solid #dfebf7;background:#fff;padding:12px;border-radius:10px; }
.branding-sample-stats small,.branding-sample-stats strong { display:block; }
.branding-sample-stats small { color:#687f98;font-size:11px; }
.branding-sample-stats strong { color:#153c73;font-size:14px;margin-top:3px; }
.branding-preview-note { margin-top:17px;padding:16px;border-left:3px solid var(--church-secondary);
  background:#f5f9ff;border-radius:8px; }
.branding-preview-note strong { color:#16447b;font-size:13px; }
.branding-preview-note p { font-size:12px; color:#6f839d;line-height:1.6;margin:5px 0 0; }
@media(max-width:1040px) {
  .branding-layout { grid-template-columns:1fr; }
  .branding-preview-panel { position:static; }
}
@media(max-width:580px) {
  .content { padding:18px 13px 28px; }
  .content .branding-panel { padding:19px; }
  .branding-upload { flex-direction:column; align-items:flex-start; }
  .branding-color-grid { grid-template-columns:1fr 1fr; gap:10px; }
  .branding-preview-brand strong { font-size:13px; }
  .branding-actions .btn { width:100%; }
  .app-topbar { padding-left:14px;padding-right:14px; }
}
@media(prefers-reduced-motion:reduce) {
  *, *::before,*::after {scroll-behavior:auto!important;animation-duration:.01ms!important;}
}


/* Formulários de entradas e saídas — navegação clara no celular */
.finance-direction-tabs{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
.finance-direction-tab{
  min-height:46px;padding:10px 12px;border-radius:11px;background:#f1f7fd;
  border:1px solid #bdd4eb;color:#27547c;cursor:pointer;font-size:13px;font-weight:750;
}
.finance-direction-tab.active{background:var(--church-primary);border-color:var(--church-primary);color:#fff}
.finance-direction-tab:focus-visible{outline:3px solid #70adff;outline-offset:2px}
.finance-direction-label{margin-bottom:6px}
.finance-tithe-choice{display:flex;align-items:center;gap:9px;margin-top:10px;
  border:1px solid #c9dfef;border-radius:10px;padding:12px;color:#184372;font-size:12px;line-height:1.5}
.finance-tithe-choice input{width:auto!important;min-height:0!important;flex:0 0 auto}
.finance-category-helper{display:flex;flex-direction:column;gap:5px}
.finance-category-helper .select{width:100%}

(() => {
  'use strict';
  const form = document.getElementById('branding-form');
  const preview = document.getElementById('branding-preview-brand');
  if (!form || !preview) return;
  const nameField = document.getElementById('branding-name');
  const taglineField = document.getElementById('branding-tagline');
  const primaryField = document.getElementById('branding-primary');
  const secondaryField = document.getElementById('branding-secondary');
  const logoField = document.getElementById('church-logo-input');
  const logoBox = document.getElementById('branding-logo-preview');
  const mark = document.getElementById('branding-preview-mark');
  let objectUrl = null;
  function update() {
    preview.style.setProperty('--church-primary', primaryField.value);
    preview.style.setProperty('--church-secondary', secondaryField.value);
    preview.querySelector('[data-brand-name]').textContent = nameField.value.trim() || 'Nome da Igreja';
    preview.querySelector('[data-brand-tagline]').textContent = taglineField.value.trim() || 'Gestão da sua igreja';
  }
  [nameField, taglineField, primaryField, secondaryField].forEach(input => input.addEventListener('input', update));
  logoField.addEventListener('change', () => {
    const file = logoField.files && logoField.files[0];
    if (!file) return;
    if (!['image/png', 'image/jpeg', 'image/webp'].includes(file.type) || file.size > 5 * 1024 * 1024) {
      logoField.setCustomValidity('Selecione uma imagem PNG, JPG ou WEBP de até 5 MB.');
      logoField.reportValidity();
      return;
    }
    logoField.setCustomValidity('');
    if (objectUrl) URL.revokeObjectURL(objectUrl);
    objectUrl = URL.createObjectURL(file);
    for (const box of [logoBox, mark]) {
      const img = document.createElement('img');
      img.src = objectUrl;
      img.alt = 'Prévia da logo escolhida';
      box.replaceChildren(img);
    }
  });
  window.addEventListener('pagehide', () => { if (objectUrl) URL.revokeObjectURL(objectUrl); });
  update();
})();

:root{--church-primary:#0D47A1;--church-secondary:#1976D2;color-scheme:light}
*,*:before,*:after{box-sizing:border-box}
body{margin:0;font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif;background:#f0f6fc;color:#15345b;min-height:100vh}
.contribute-shell{width:min(100%,620px);margin:0 auto;padding:22px 16px 34px}
.contribute-header{display:flex;align-items:center;gap:14px;padding:12px 10px 22px}
.contribute-mark{display:grid;place-items:center;width:70px;height:70px;flex:0 0 70px;border-radius:17px;background:#fff;color:var(--church-primary);box-shadow:0 4px 15px #1c4c7d17;font-size:37px;overflow:hidden}
.contribute-mark img{width:100%;height:100%;object-fit:contain;padding:6px}
.contribute-header strong,.contribute-header small{display:block}
.contribute-header strong{font-size:18px;line-height:1.25;color:#103e79}
.contribute-header small{font-size:12px;color:#6b829c;margin-top:5px}
.contribute-card{background:#fff;border:1px solid #dfeaf6;border-radius:23px;padding:26px;box-shadow:0 10px 34px #143b6a12}
.contribute-intro{text-align:center;background:#eaf4ff;padding:26px 20px;border-radius:17px;margin-bottom:25px}
.contribute-eyebrow{font-size:11px;text-transform:uppercase;font-weight:750;letter-spacing:.1em;color:var(--church-primary)}
.contribute-intro h1{font-size:24px;line-height:1.25;color:#103a75;margin:8px 0}
.contribute-intro p{margin:0;color:#44617f;font-size:13px}
.contribute-intro blockquote{font-style:italic;font-size:13px;margin:16px 10px 0;color:#35597d;line-height:1.6}
.contribute-intro blockquote strong{display:block;font-style:normal}
.contribute-form{display:grid;gap:18px}
.contribute-field{display:grid;gap:7px}
.contribute-field label{font-size:14px;font-weight:720;color:#133c70}
.contribute-field em{color:#b8273f;font-style:normal}
.contribute-field select,.contribute-field input,.contribute-field textarea{width:100%;min-height:48px;border:1px solid #cdddea;border-radius:11px;padding:12px 13px;background:#fff;color:#1c3a5d;font-size:15px;font-family:inherit;outline:0}
.contribute-field textarea{resize:vertical;min-height:86px}
.contribute-field input[type=file]{font-size:12px;padding:14px}
.contribute-field input:focus-visible,.contribute-field select:focus-visible,.contribute-field textarea:focus-visible{border-color:var(--church-secondary);box-shadow:0 0 0 3px #1976d22b}
.contribute-field small{font-size:12px;color:#6d8096}
.contribute-optional-heading{font-weight:760;font-size:13px;color:#144379;background:#eaf4ff;border-radius:9px;padding:11px 14px;margin-top:3px}
.contribute-button{display:flex;align-items:center;justify-content:center;min-height:54px;border:0;border-radius:11px;width:100%;background:var(--church-primary);color:#fff;font-weight:750;text-decoration:none;font-size:16px;cursor:pointer;padding:12px 16px}
.contribute-button:hover{filter:brightness(.92)}
.contribute-notice{font-size:11px;color:#70849b;line-height:1.6;text-align:center;margin:0}
.contribute-honeypot{position:absolute;left:-10000px;opacity:0;height:0;width:0;overflow:hidden}
.contribute-error{background:#fff1f3;border:1px solid #f4b9c1;border-radius:10px;color:#8d2030;font-size:13px;padding:12px 15px}
.contribute-success{text-align:center}.contribute-success h1{color:#153f73}.contribute-success p{font-size:14px;line-height:1.7;color:#536b83}
.contribute-success-icon{width:68px;height:68px;border-radius:50%;margin:12px auto;background:#e7f7ec;color:#168142;display:grid;place-items:center;font-size:36px}
.contribute-success .contribute-button{margin-top:24px}
.contribute-footer{text-align:center;color:#7890aa;font-size:11px;padding-top:20px}
@media(max-width:540px){.contribute-shell{padding:12px 10px 26px}.contribute-card{border-radius:18px;padding:18px}.contribute-mark{width:58px;height:58px;flex-basis:58px}.contribute-header strong{font-size:15px}.contribute-intro{padding:22px 12px}.contribute-intro h1{font-size:20px}}

(() => {
 'use strict';
 const type=document.getElementById('contribute-type');
 const payment=document.getElementById('contribute-method');
 const campaign=document.getElementById('contribute-campaign');
 const ref=document.getElementById('contribute-ref');
 if(!type||!payment) return;
 const update=()=>{
   const needsCampaign=type.selectedOptions[0]?.dataset.campaign==='1';
   const needsRef=payment.selectedOptions[0]?.dataset.reference==='1';
   document.getElementById('contribute-campaign-field').hidden=!needsCampaign;
   document.getElementById('contribute-ref-field').hidden=!needsRef;
   if(campaign)campaign.required=needsCampaign;
   if(ref)ref.required=needsRef;
 };
 type.addEventListener('change',update);
 payment.addEventListener('change',update);
 update();
})();

/* Igreja Master 3.7.26 — telas de entrada e saída.
 * Formata reais; categoriza; sugere histórico; valida campos condicionais.
 * Não transmite dados financeiros fora do formulário e não grava sem confirmação.
 */
(() => {
 'use strict';
 const brl=new Intl.NumberFormat('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
 const parseAmount = raw => {
   let str=String(raw??'').trim().replace(/\s|R\$/g,'');
   if (/^\d{1,3}(\.\d{3})+(,\d{1,2})?$/.test(str)) str=str.replaceAll('.','').replace(',','.');
   else if (/^\d{1,10}(,\d{1,2})?$/.test(str)) str=str.replace(',','.');
   if (!/^\d{1,10}(\.\d{1,2})?$/.test(str)) return null;
   const value=Number(str);
   return Number.isFinite(value)&&value>0&&value<=999999999.99?value:null;
 };
 const dateString=iso=>{
   const m=String(iso??'').match(/^(\d{4})-(\d{2})-(\d{2})$/);
   return m ? m[3]+'/'+m[2]+'/'+m[1] : '';
 };
 const init=form=>{
   if(!form.querySelector('input[name="action"][value="entry"]'))return;
   const amount=form.querySelector('input[name="amount"]');
   const category=form.querySelector('input[name="category"]');
   const direction=form.querySelector('select[name="direction"]');
   const description=form.querySelector('input[name="description"]');
   const date=form.querySelector('input[name="transaction_date"]');
   const member=form.querySelector('select[name="member_id"]');
   const memberBox=form.querySelector('[data-finance-member-field]');
   const tithe=form.querySelector('input[name="tithe_identified"]');
   const titheBox=form.querySelector('[data-finance-tithe-choice]');
   const payment=form.querySelector('select[name="payment_method"]');
   const reference=form.querySelector('input[name="document_number"]');
   const referenceHint=form.querySelector('[data-finance-bank-reference-hint]');
   const submit=form.querySelector('button[type="submit"]');
   if(!amount||!category||!direction)return;

   amount.addEventListener('input',()=>{amount.setCustomValidity('');amount.removeAttribute('aria-invalid');});
   amount.addEventListener('blur',()=>{const value=parseAmount(amount.value);if(value!==null)amount.value=brl.format(value);});
   const datalist=document.getElementById(category.getAttribute('list')||'');
   if(datalist){
     const registered=[...new Set([...datalist.querySelectorAll('option')].map(x=>x.value.trim()).filter(Boolean))]
       .sort((a,b)=>a.localeCompare(b,'pt-BR'));
     if(registered.length){
       const helper=document.createElement('div');
       helper.className='finance-category-helper';
       const hint=document.createElement('small');
       hint.className='muted';hint.textContent='Pesquise pelo nome acima ou selecione uma categoria cadastrada.';
       const picker=document.createElement('select');picker.className='select';
       picker.setAttribute('aria-label','Categorias disponíveis');
       const opt=document.createElement('option');opt.value='';opt.textContent='Selecionar categoria existente';picker.append(opt);
       registered.forEach(name=>{const o=document.createElement('option');o.value=name;o.textContent=name;picker.append(o);});
       picker.addEventListener('change',()=>{if(picker.value){category.value=picker.value;category.dispatchEvent(new Event('input',{bubbles:true}));}});
       category.addEventListener('input',()=>{if(picker.value!==category.value)picker.value='';});
       helper.append(picker,hint);
       const host=category.closest('.field')||category.closest('label');
       host?.after(helper);
     }
   }

   // Botões distintos de Entrada/Saída tornam o fluxo mais evidente no celular.
   const directionHost=direction.closest('.field');
   if(directionHost){
     const tabs=document.createElement('div');
     tabs.className='finance-direction-tabs';
     tabs.setAttribute('role','group');
     tabs.setAttribute('aria-label','Tipo de lançamento');
     const buttons={};
     for(const [key,text,icon] of [['income','Entrada','＋'],['expense','Saída','−']]){
       const b=document.createElement('button');
       b.type='button';b.className='finance-direction-tab';
       b.dataset.direction=key;b.textContent=icon+' '+text;
       b.addEventListener('click',()=>{direction.value=key;direction.dispatchEvent(new Event('change',{bubbles:true}));});
       tabs.append(b);buttons[key]=b;
     }
     directionHost.prepend(tabs);
     direction.hidden=true;
     directionHost.querySelector('label')?.classList.add('finance-direction-label');
     direction.dataset.syncTabs='1';
     const updateTabs=()=>{
       Object.entries(buttons).forEach(([key,b])=>{
         const on=key===direction.value;
         b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on));
       });
     };
     direction.addEventListener('change',updateTabs);updateTabs();
   }
   let lastAuto='';
   let userEdited=false;
   description?.addEventListener('input',()=>{
     if(description.value.trim()!==lastAuto)userEdited=true;
     if(!description.value.trim())userEdited=false;
   });
   const isTithe=()=>/d[ií]zimo/iu.test(category.value);
   const needsReference=()=>direction.value==='income'&&/pix|transfer[êe]ncia/iu.test(payment?.value||'');
   const update=()=>{
     const expense=direction.value==='expense';
     category.placeholder=expense?'Ex.: Material de limpeza':'Ex.: Dízimos, Ofertas, Missões';
     if(submit && form.dataset.financeSubmitting!=='1') submit.textContent=expense?'Registrar saída':'Registrar entrada';
     if(memberBox)memberBox.hidden=expense;
     if(titheBox)titheBox.hidden=expense||!isTithe();
     if(tithe&&(expense||!isTithe()))tithe.checked=false;
     if(member)member.required=!!(tithe?.checked&&!expense&&isTithe());
     if(reference){reference.required=needsReference();reference.placeholder=needsReference()?'ID Pix ou autenticação obrigatória':'Número do documento (opcional)';}
     if(referenceHint)referenceHint.hidden=!needsReference();
     if(description){
       const type=category.value.trim();
       if(!expense&&type&&(!userEdited||description.value.trim()==='')){
         const label=isTithe()&&tithe?.checked?'Dízimo identificado':type.replace(/s$/,'');
         const method=payment?.value.trim()||'forma não informada';
         const when=dateString(date?.value);
         const generated=label+' recebido via '+method+(when?' em '+when:'');
         description.value=generated;lastAuto=generated;userEdited=false;
       } else if(expense && description.value===lastAuto){
         description.value='';lastAuto='';userEdited=false;
       }
       if(!description.value)description.placeholder=expense?'Descreva o pagamento':'Descrição da contribuição';
     }
   };
   [direction,category,payment,date,member,tithe].filter(Boolean).forEach(el=>el.addEventListener('change',update));
   category.addEventListener('input',update);
   update();

   form.addEventListener('submit',event=>{
     if(form.dataset.financeSubmitting==='1'){event.preventDefault();return;}
     const n=parseAmount(amount.value);
     if(n===null){event.preventDefault();amount.setCustomValidity('Informe um valor positivo válido, em reais.');amount.setAttribute('aria-invalid','true');amount.reportValidity();return;}
     if(needsReference() && !reference?.value.trim()){event.preventDefault();reference?.setCustomValidity('Informe a referência Pix ou transferência.');reference?.reportValidity();return;}
     if(tithe?.checked && isTithe() && !member?.value){event.preventDefault();member?.setCustomValidity('Selecione o membro para dízimo identificado.');member?.reportValidity();return;}
     if(reference)reference.setCustomValidity('');
     if(member)member.setCustomValidity('');
     amount.value=brl.format(n);
     form.dataset.financeSubmitting='1';
     window.requestAnimationFrame(()=>{
       if(event.defaultPrevented){delete form.dataset.financeSubmitting;return;}
       if(submit){submit.disabled=true;submit.textContent='Registrando…';}
     });
   });
 };
 document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('form').forEach(init);});
})();
